import React, { useState, useEffect, useContext } from 'react';
import { AppContext } from '../context/AppContext';
import { useNavigate } from 'react-router-dom';

const OrdersPage = () => {
  const [orders, setOrders] = useState([]);
  const { fetchOrders, loading, user } = useContext(AppContext);
  const navigate = useNavigate();

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    loadOrders();
  }, [user]);

  const loadOrders = async () => {
    const data = await fetchOrders();
    setOrders(data);
  };

  return (
    <div className="max-w-5xl mx-auto mt-12 px-4">
      <h1 className="text-3xl font-bold mb-8 text-gray-800">My Orders</h1>
      {loading && <p className="text-center">Loading...</p>}
      {orders.length === 0 ? (
        <p className="text-center text-xl text-gray-600 py-8">No orders yet</p>
      ) : (
        <div className="grid gap-4">
          {orders.map(order => (
            <div key={order._id} className="bg-white p-6 rounded-lg shadow-md border border-gray-200 hover:shadow-lg transition-shadow">
              <h3 className="text-xl font-bold text-gray-800 mb-3">{order.bookId?.title}</h3>
              <p className="text-gray-600 mb-1"><span className="font-semibold">Author:</span> {order.bookId?.author}</p>
              <p className="text-gray-600 mb-1"><span className="font-semibold">Quantity:</span> {order.quantity} books</p>
              <p className="text-gray-600 mb-1"><span className="font-semibold">Price per book:</span> ₹{order.bookId?.price}</p>
              <p className="text-green-600 font-bold text-xl mb-3"><span className="font-semibold text-gray-600">Total Amount:</span> ₹{order.totalAmount}</p>

              <div className="bg-blue-50 p-4 rounded-lg mb-3">
                <p className="font-semibold text-gray-800 mb-2">Shipping Address:</p>
                <p className="text-gray-700">{order.shippingAddress?.name}</p>
                <p className="text-gray-700">{order.shippingAddress?.phone}</p>
                <p className="text-gray-700">{order.shippingAddress?.address}</p>
                <p className="text-gray-700">{order.shippingAddress?.city} - {order.shippingAddress?.pincode}</p>
              </div>

              <p className="text-gray-600 mb-1"><span className="font-semibold">Order Date:</span> {new Date(order.orderDate).toLocaleDateString()}</p>
              <p className="text-gray-600"><span className="font-semibold">Status:</span> <span className="text-green-600 capitalize font-semibold">{order.status}</span></p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default OrdersPage;
